// Aggregate all GitHub data into a summary object
const commits = $input.all()[0].json;
const issues = $input.all()[1].json;
const prs = $input.all()[2].json;

const summary = {
  repo: $('Set Repo URL').item.json.repo_name,
  week: `${$('Set Repo URL').item.json.week_start} to ${$('Set Repo URL').item.json.week_end}`,
  commits: (Array.isArray(commits) ? commits : []).map(c => ({
    message: c.commit?.message?.split('\n')[0] || '',
    author: c.commit?.author?.name || c.author?.login || '',
    date: c.commit?.author?.date || ''
  })),
  issues_closed: (Array.isArray(issues) ? issues : [])
    .filter(i => !i.pull_request)
    .map(i => ({
      title: i.title,
      number: i.number,
      labels: (i.labels || []).map(l => l.name)
    })),
  prs_merged: (Array.isArray(prs) ? prs : [])
    .filter(p => p.merged_at)
    .map(p => ({
      title: p.title,
      number: p.number,
      author: p.user?.login || '',
      merged_at: p.merged_at
    }))
};

return { json: summary };

const data = $input.first().json;
const commitCount = data.commits.length;
const issueCount = data.issues_closed.length;
const prCount = data.prs_merged.length;

// Build commit summary
const commitList = data.commits.slice(0, 10).map(c => `- ${c.message}`).join('\n');

// Build PR summary
const prList = data.prs_merged.map(p => `- #${p.number}: ${p.title} (@${p.author})`).join('\n');

// Build issue summary
const issueList = data.issues_closed.map(i => `- #${i.number}: ${i.title}`).join('\n');

const prompt = `You are a weekly dev summary writer. Write a concise, narrative summary for the project "${data.repo}" for the week of ${data.week}.

Stats:
- ${commitCount} commits
- ${prCount} PRs merged
- ${issueCount} issues closed

${commitCount > 0 ? 'Commits:\n' + commitList : 'No commits this week.'}

${prCount > 0 ? 'PRs Merged:\n' + prList : 'No PRs merged this week.'}

${issueCount > 0 ? 'Issues Closed:\n' + issueList : 'No issues closed this week.'}

Write a 2-4 paragraph summary. Format:
- First paragraph: high-level overview
- Second: notable PRs/features merged
- Third: issues resolved and ongoing themes
- Keep it informative but friendly. Do NOT use markdown headers.`;

return { json: { ...data, prompt } };

const response = $input.first().json;
const content = response.content?.[0]?.text || 'No summary generated.';

// Add header
const header = `# 📊 Weekly Dev Summary\n\n**${$('Aggregate Data').first().json.repo}** — ${$('Aggregate Data').first().json.week}\n\n`;

return { json: { summary: header + content } };

// Set the repo URL, name, and date range for the week
const now = new Date();
const dayOfWeek = now.getDay();
const daysToLastFriday = dayOfWeek >= 5 ? dayOfWeek - 5 : dayOfWeek + 2;
const lastFriday = new Date(now);
lastFriday.setDate(now.getDate() - daysToLastFriday - 7);
const weekStart = lastFriday.toISOString().split('T')[0];
const weekEnd = now.toISOString().split('T')[0];

return {
  json: {
    repo_url: 'https://api.github.com/repos/REPO_OWNER/REPO_NAME',
    repo_name: 'REPO_OWNER/REPO_NAME',
    week_start: weekStart,
    week_end: weekEnd
  }
};
